:150px">Price</th><th class="text-end">Total</th></tr></thead><tbody><?php $__currentLoopData = $order->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $index => $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><input type="hidden" name="items[<?php echo e($index); ?>][product_id]" value="<?php echo e($item->product_id); ?>"><input class="form-control-plaintext fw-semibold" name="items[<?php echo e($index); ?>][product_name]" value="<?php echo e($item->product_name); ?>" readonly></td><td><input type="number" min="0.01" step="0.01" class="form-control" name="items[<?php echo e($index); ?>][quantity]" value="<?php echo e($item->quantity); ?>"></td><td><input type="number" min="0" step="0.01" class="form-control" name="items[<?php echo e($index); ?>][unit_price]" value="<?php echo e($item->unit_price); ?>"></td><td class="text-end fw-bold">$<?php echo e(number_format($item->line_total,2)); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div></div></div><div class="col-xl-4"><div class="panel"><div class="panel-heading mb-3">Finish this draft</div><p class="text-muted small">The saved products are ready. You can adjust quantity or price above, then either keep the draft or finish the sale.</p><div class="d-grid gap-2"><button class="btn btn-outline-primary" name="status" value="draft"><i class="bi bi-pause-circle me-1"></i>Save draft</button><button class="btn text-white" style="background:var(--brand)" name="status" value="completed"><i class="bi bi-credit-card me-1"></i>Complete sale</button><a class="btn btn-light" href="<?php echo e(route('admin.pos.drafts')); ?>">Cancel</a></div></div></div></div></form>
